return [{ json: {
  supabase_url: 'https://horvjqqifgrzxesuxtfm.supabase.co',
  supabase_service_role_key: 'REPLACE_WITH_HUB_SERVICE_ROLE_KEY',
  lookback_days: 30,
  publication_limit: 75
} }];

const cfg = $('Config').item.json;
const input = $input.all();
const rows = input.flatMap(item => Array.isArray(item.json) ? item.json : [item.json]).filter(Boolean);

function extractVideoId(row) {
  if (row.external_id && /^[A-Za-z0-9_-]{11}$/.test(String(row.external_id))) return String(row.external_id);
  const url = String(row.external_url || row.response?.youtube_url || row.response?.url || '');
  const patterns = [
    /youtu\.be\/([A-Za-z0-9_-]{11})/,
    /[?&]v=([A-Za-z0-9_-]{11})/,
    /\/shorts\/([A-Za-z0-9_-]{11})/,
    /\/embed\/([A-Za-z0-9_-]{11})/,
    /([A-Za-z0-9_-]{11})/
  ];
  for (const pattern of patterns) {
    const match = url.match(pattern);
    if (match) return match[1];
  }
  return null;
}

function isoDate(date) {
  return date.toISOString().slice(0, 10);
}

const now = new Date();
const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - 1));
const minStart = new Date(end);
minStart.setUTCDate(minStart.getUTCDate() - Math.max(1, Number(cfg.lookback_days || 30)) + 1);

const jobs = [];
for (const row of rows) {
  const videoId = extractVideoId(row);
  if (!videoId || !row.episode_id || !row.id) continue;
  const published = row.published_at ? new Date(row.published_at) : minStart;
  const publishedDate = Number.isNaN(published.getTime()) ? minStart : published;
  const start = new Date(Math.max(minStart.getTime(), Date.UTC(publishedDate.getUTCFullYear(), publishedDate.getUTCMonth(), publishedDate.getUTCDate())));
  const safeStart = start.getTime() > end.getTime() ? end : start;
  jobs.push({ json: {
    publication_id: row.id,
    episode_id: row.episode_id,
    youtube_video_id: videoId,
    external_url: row.external_url || `https://youtu.be/${videoId}`,
    start_date: isoDate(safeStart),
    end_date: isoDate(end)
  } });
}

return jobs;

const analyticsItems = $input.all();
const jobItems = $items('Build Video Jobs');
const statsItems = $items('YouTube Video Stats');
const output = [];

function numberValue(value) {
  const n = Number(value || 0);
  return Number.isFinite(n) ? n : 0;
}

function buildRow(job, stats, values) {
  const date = String(values.day || job.end_date).slice(0, 10);
  return {
    episode_id: job.episode_id,
    publication_id: job.publication_id,
    youtube_video_id: job.youtube_video_id,
    metric_date: date,
    views: Math.round(numberValue(values.views)),
    engaged_views: 0,
    estimated_minutes_watched: numberValue(values.estimatedMinutesWatched),
    average_view_duration: numberValue(values.averageViewDuration),
    average_view_percentage: numberValue(values.averageViewPercentage),
    likes: Math.round(numberValue(stats.likeCount)),
    comments: Math.round(numberValue(stats.commentCount)),
    shares: 0,
    subscribers_gained: Math.round(numberValue(values.subscribersGained)),
    subscribers_lost: Math.round(numberValue(values.subscribersLost)),
    traffic_sources: {},
    countries: {},
    raw: {
      analytics_row: values,
      public_statistics: stats,
      external_url: job.external_url,
      sync_window: { start_date: job.start_date, end_date: job.end_date }
    },
    synced_at: new Date().toISOString()
  };
}

analyticsItems.forEach((item, index) => {
  const analytics = item.json || {};
  const job = jobItems[index]?.json;
  const stats = statsItems[index]?.json?.items?.[0]?.statistics || {};
  if (!job) return;

  const headers = Array.isArray(analytics.columnHeaders) ? analytics.columnHeaders.map(h => h.name) : [];
  const rows = Array.isArray(analytics.rows) ? analytics.rows : [];

  if (!rows.length) {
    output.push({ json: buildRow(job, stats, { day: job.end_date }) });
    return;
  }

  for (const row of rows) {
    const values = {};
    headers.forEach((name, headerIndex) => { values[name] = row[headerIndex]; });
    output.push({ json: buildRow(job, stats, values) });
  }
});

return output;
